"""Vendor the two upstream prompts as shared skills; never execute upstream code."""

from __future__ import annotations

import argparse
from dataclasses import asdict, dataclass
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import sys
import tempfile
from urllib.parse import quote
from urllib.request import Request, urlopen


ROOT = Path(__file__).resolve().parent.parent
MAX_BYTES = 1024 * 1024
GENERATED_NOTICE = (
    "# Generated by scripts/sync_upstream_skills.py; do not edit.\n"
    "# Adapted from a Claude agent: model metadata removed; prompt body unchanged.\n"
)


@dataclass(frozen=True)
class Source:
    name: str
    repository: str
    branch: str
    prompt_path: str
    license_path: str
    format: str


def load_sources(root: Path) -> list[Source]:
    manifest = json.loads((root / "scripts/upstream_skills.json").read_text())
    if manifest.get("version") != 1:
        raise ValueError("Unsupported upstream skills manifest version")
    sources = [Source(**entry) for entry in manifest["skills"]]
    names = set()
    for source in sources:
        if not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", source.name):
            raise ValueError(f"Invalid skill name: {source.name}")
        if source.name in names:
            raise ValueError(f"Duplicate skill: {source.name}")
        names.add(source.name)
        if not re.fullmatch(r"[\w.-]+/[\w.-]+", source.repository):
            raise ValueError(f"Invalid repository: {source.repository}")
        for path in (source.prompt_path, source.license_path):
            if not path or PurePosixPath(path).is_absolute() or ".." in path.split("/"):
                raise ValueError(f"Invalid upstream path: {path}")
        if not source.branch or source.format not in {"skill", "claude-agent"}:
            raise ValueError(f"Invalid source configuration: {source.name}")
    return sources


def fetch_url(url: str) -> bytes:
    headers = {"User-Agent": "clusterfork-upstream-skills"}
    token = os.environ.get("GH_TOKEN") or os.environ.get("GITHUB_TOKEN")
    if token and url.startswith("https://api.github.com/"):
        headers["Authorization"] = f"Bearer {token}"
    with urlopen(Request(url, headers=headers), timeout=30) as response:
        data = response.read(MAX_BYTES + 1)
    if len(data) > MAX_BYTES:
        raise ValueError(f"Upstream file exceeds {MAX_BYTES} bytes: {url}")
    return data


def render_skill(source: Source, prompt: bytes) -> bytes:
    text = prompt.decode("utf-8")
    match = re.fullmatch(r"---\n(.*?)\n---\n(.*)", text, flags=re.DOTALL)
    if not match or not match[2].strip():
        raise ValueError(f"Missing frontmatter or prompt body: {source.name}")
    header, body = match.groups()
    name = re.search(r"^name:\s*([^\n]+)$", header, flags=re.MULTILINE)
    if not name or name[1].strip().strip("\"'") != source.name:
        raise ValueError(f"Upstream skill name does not match {source.name}")
    if not re.search(r"^description:[ \t]*\S", header, flags=re.MULTILINE):
        raise ValueError(f"Missing description: {source.name}")
    if source.format == "skill":
        return prompt
    keys = set(re.findall(r"^([\w-]+):", header, flags=re.MULTILINE))
    if keys - {"name", "description", "model"}:
        raise ValueError(f"Unsupported Claude agent metadata in {source.name}: {sorted(keys)}")
    if re.search(r"^model:[ \t]*[>|]", header, flags=re.MULTILINE):
        raise ValueError(f"Unsupported multiline model in {source.name}")
    header = re.sub(r"^model:[^\n]*(?:\n|$)", "", header, flags=re.MULTILINE)
    return f"---\n{GENERATED_NOTICE}{header.rstrip()}\n---\n{body}".encode("utf-8")


def build_files(source: Source, commit: str, prompt: bytes, license_text: bytes) -> dict[str, bytes]:
    if not re.fullmatch(r"[0-9a-f]{40}", commit):
        raise ValueError(f"Invalid upstream commit for {source.name}")
    if not license_text.decode("utf-8").strip():
        raise ValueError(f"Empty upstream license for {source.name}")
    files = {"SKILL.md": render_skill(source, prompt), "LICENSE": license_text}
    if source.format == "claude-agent":
        files["UPSTREAM.md"] = prompt
    metadata = {
        **asdict(source),
        "commit": commit,
        "prompt_sha256": hashlib.sha256(prompt).hexdigest(),
        "license_sha256": hashlib.sha256(license_text).hexdigest(),
        "adapter_version": 1,
    }
    files["UPSTREAM.json"] = (json.dumps(metadata, indent=2) + "\n").encode("utf-8")
    return files


def destination_for(root: Path, source: Source) -> Path | None:
    if (root / "disabled-skills" / source.name).is_dir():
        return None
    destination = root / "skills" / source.name
    if destination.is_symlink() or not destination.resolve().is_relative_to(root.resolve()):
        raise ValueError(f"Skill destination escapes the repository: {source.name}")
    for name in ("SKILL.md", "LICENSE", "UPSTREAM.md", "UPSTREAM.json"):
        if (destination / name).is_symlink():
            raise ValueError(f"Refusing to overwrite symlink: {destination / name}")
    return destination


def same_snapshot(destination: Path, files: dict[str, bytes]) -> bool:
    """An unrelated upstream commit must not create a daily metadata-only commit."""
    for name, content in files.items():
        if name == "UPSTREAM.json":
            continue
        path = destination / name
        if not path.is_file() or path.read_bytes() != content:
            return False
    try:
        previous = json.loads((destination / "UPSTREAM.json").read_bytes())
        current = json.loads(files["UPSTREAM.json"])
    except (OSError, ValueError):
        return False
    if not isinstance(previous, dict) or not re.fullmatch(r"[0-9a-f]{40}", str(previous.get("commit", ""))):
        return False
    previous.pop("commit", None)
    current.pop("commit")
    return previous == current


def sync(root: Path, sources: list[Source], fetch=fetch_url) -> list[Path]:
    pending = []
    # Fetch and validate every source before modifying any local file.
    for source in sources:
        destination = destination_for(root, source)
        if destination is None:
            continue
        revision_url = (
            f"https://api.github.com/repos/{source.repository}/commits/"
            f"{quote(source.branch, safe='')}"
        )
        commit = json.loads(fetch(revision_url))["sha"]
        if not isinstance(commit, str) or not re.fullmatch(r"[0-9a-f]{40}", commit):
            raise ValueError(f"Invalid upstream commit for {source.name}")
        base = f"https://raw.githubusercontent.com/{source.repository}/{commit}/"
        prompt = fetch(base + quote(source.prompt_path, safe="/"))
        license_text = fetch(base + quote(source.license_path, safe="/"))
        files = build_files(source, commit, prompt, license_text)
        if not same_snapshot(destination, files):
            pending.append((destination, files))
    changed = []
    for destination, files in pending:
        destination.mkdir(parents=True, exist_ok=True)
        for name, content in files.items():
            target = destination / name
            if target.is_file() and target.read_bytes() == content:
                continue
            temporary = None
            try:
                with tempfile.NamedTemporaryFile(dir=destination, delete=False) as handle:
                    temporary = Path(handle.name)
                    handle.write(content)
                temporary.chmod(0o644)
                temporary.replace(target)
            finally:
                if temporary is not None:
                    temporary.unlink(missing_ok=True)
            changed.append(target)
    return changed


def check(root: Path, sources: list[Source]) -> None:
    """Verify checked-in snapshots and adapters without contacting GitHub."""
    for source in sources:
        destination = destination_for(root, source)
        if destination is None:
            continue
        metadata = json.loads((destination / "UPSTREAM.json").read_bytes())
        prompt_name = "UPSTREAM.md" if source.format == "claude-agent" else "SKILL.md"
        expected = build_files(
            source, metadata["commit"], (destination / prompt_name).read_bytes(),
            (destination / "LICENSE").read_bytes(),
        )
        for name, content in expected.items():
            if (destination / name).read_bytes() != content:
                raise ValueError(f"Modified upstream snapshot: {destination / name}")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Validate local snapshots offline")
    args = parser.parse_args()
    try:
        sources = load_sources(ROOT)
        if args.check:
            check(ROOT, sources)
            print("Upstream skill snapshots verified (offline).")
        else:
            changed = sync(ROOT, sources)
            for path in changed:
                print(f"Updated {path.relative_to(ROOT)}")
            if not changed:
                print("Upstream skills are unchanged.")
    except (OSError, ValueError, KeyError, TypeError) as error:
        print(f"Upstream skill sync failed: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
